-- EDash: core data model (PostgreSQL 16)
-- Scope: Phase 1 (identity, wallet ledger, payments, bills, merchants, admin)
-- plus the Phase 2 to 4 tables later modules need, so foreign keys don't change later.
--
-- Conventions
--   * Money is BIGINT in minor units (1 ETB = 100 santim) plus a CHAR(3) ISO 4217 currency. Never floats.
--   * IDs are UUIDv7 (time-ordered) generated by the application; the default here is a fallback.
--   * Every table has created_at; mutable tables also have updated_at, maintained by the app.
--   * Each domain owns a schema. Services read other domains only through APIs or events, never by joins.
--   * Customer funds are held by licensed partners. The ledger records our view of those funds and
--     is reconciled daily against partner statements (see recon schema).

CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS citext;

CREATE SCHEMA identity;
CREATE SCHEMA ledger;
CREATE SCHEMA payments;
CREATE SCHEMA bills;
CREATE SCHEMA merchant;
CREATE SCHEMA commerce;
CREATE SCHEMA delivery;
CREATE SCHEMA rewards;
CREATE SCHEMA miniapp;
CREATE SCHEMA risk;
CREATE SCHEMA recon;
CREATE SCHEMA admin;
CREATE SCHEMA platform;
CREATE SCHEMA notify;

-- ---------------------------------------------------------------------------
-- Shared types
-- ---------------------------------------------------------------------------
CREATE TYPE platform.currency AS ENUM ('ETB', 'USD', 'EUR', 'GBP', 'KES', 'AED', 'SAR');
CREATE TYPE platform.locale AS ENUM ('am', 'om', 'ti', 'en');

-- ---------------------------------------------------------------------------
-- IDENTITY: users, devices, credentials, KYC
-- ---------------------------------------------------------------------------
CREATE TYPE identity.user_status AS ENUM ('pending', 'active', 'restricted', 'frozen', 'closed');
CREATE TYPE identity.kyc_level AS ENUM ('L0', 'L1', 'L2', 'L3');  -- L0 phone only, L1 name+DOB, L2 Fayda ID, L3 enhanced due diligence

CREATE TABLE identity.users (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    phone_e164      TEXT NOT NULL UNIQUE CHECK (phone_e164 ~ '^\+[1-9][0-9]{7,14}$'),
    email           CITEXT UNIQUE,
    display_name    TEXT,
    legal_name      TEXT,                       -- encrypted at the application layer (envelope encryption, KMS)
    date_of_birth   DATE,
    locale          platform.locale NOT NULL DEFAULT 'am',
    home_currency   platform.currency NOT NULL DEFAULT 'ETB',
    status          identity.user_status NOT NULL DEFAULT 'pending',
    kyc_level       identity.kyc_level NOT NULL DEFAULT 'L0',
    is_diaspora     BOOLEAN NOT NULL DEFAULT FALSE,
    country_code    CHAR(2) NOT NULL DEFAULT 'ET',
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE identity.devices (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id             UUID NOT NULL REFERENCES identity.users(id),
    fingerprint_hash    TEXT NOT NULL,          -- hash of device attestation; raw signals live in risk
    platform            TEXT NOT NULL CHECK (platform IN ('android', 'ios', 'web')),
    model               TEXT,
    biometric_key_pub   TEXT,                   -- P-256 SPKI (base64 DER) of the device's biometric-gated key; set only with the PIN, cleared by a PIN reset
    biometric_enrolled_at TIMESTAMPTZ,
    -- Android key attestation of the last sign-in's DPoP key (NULL: not checked, e.g. iOS or attestation off).
    key_attestation     TEXT CHECK (key_attestation IN ('strongbox', 'tee', 'none', 'failed')),
    verified_boot       TEXT CHECK (verified_boot IN ('verified', 'self_signed', 'unverified', 'failed')),
    device_locked       BOOLEAN,                -- bootloader locked, as the attestation reports it
    os_patch_level      INT,                    -- YYYYMM
    key_attested_at     TIMESTAMPTZ,
    biometric_key_attestation TEXT CHECK (biometric_key_attestation IN ('strongbox', 'tee', 'none', 'failed')),
    trusted             BOOLEAN NOT NULL DEFAULT FALSE,
    first_seen_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_seen_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    revoked_at          TIMESTAMPTZ,
    UNIQUE (user_id, fingerprint_hash)
);

CREATE TABLE identity.credentials (
    user_id         UUID PRIMARY KEY REFERENCES identity.users(id),
    pin_hash        TEXT NOT NULL,              -- argon2id
    pin_failures    SMALLINT NOT NULL DEFAULT 0,
    locked_until    TIMESTAMPTZ,
    reset_at        TIMESTAMPTZ,                -- last PIN reset by SMS code; payments are held for a cooling-off period after it
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE identity.otp_challenges (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    phone_e164      TEXT NOT NULL,
    purpose         TEXT NOT NULL CHECK (purpose IN ('signup', 'login', 'pin_reset', 'device_bind', 'step_up')),
    code_hash       TEXT NOT NULL,
    attempts        SMALLINT NOT NULL DEFAULT 0,
    expires_at      TIMESTAMPTZ NOT NULL,
    consumed_at     TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX ON identity.otp_challenges (phone_e164, created_at DESC);

CREATE TABLE identity.sessions (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id             UUID NOT NULL REFERENCES identity.users(id),
    device_id           UUID NOT NULL REFERENCES identity.devices(id),
    refresh_token_hash  TEXT NOT NULL UNIQUE,   -- rotated on every refresh; reuse revokes the family
    family_id           UUID NOT NULL,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at          TIMESTAMPTZ NOT NULL,
    revoked_at          TIMESTAMPTZ,            -- set on rotation, logout or family revocation
    pin_reset_until     TIMESTAMPTZ,            -- session came from a pin_reset code: may set a new PIN once, until this time
    dpop_jkt            TEXT                    -- RFC 7638 thumbprint of the device key the session is bound to (DPoP); NULL = bearer
);
CREATE INDEX ON identity.sessions (user_id) WHERE revoked_at IS NULL;
CREATE INDEX ON identity.sessions (family_id);

-- DPoP proofs already used, kept until they would be too old to pass anyway (replay protection).
CREATE TABLE identity.dpop_proofs (
    jkt         TEXT NOT NULL,
    jti         TEXT NOT NULL,
    expires_at  TIMESTAMPTZ NOT NULL,
    PRIMARY KEY (jkt, jti)
);
CREATE INDEX ON identity.dpop_proofs (expires_at);

CREATE TABLE identity.kyc_verifications (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id         UUID NOT NULL REFERENCES identity.users(id),
    level           identity.kyc_level NOT NULL,
    method          TEXT NOT NULL CHECK (method IN ('fayda', 'passport', 'kebele_id', 'partner_bank', 'manual')),
    provider_ref    TEXT,                       -- reference at the ID provider; no document images stored here
    status          TEXT NOT NULL CHECK (status IN ('pending', 'approved', 'rejected', 'expired')),
    reviewed_by     UUID,                       -- admin.staff id for manual reviews
    decided_at      TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE identity.addresses (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id         UUID NOT NULL REFERENCES identity.users(id),
    label           TEXT NOT NULL,              -- Home, Office, Mum
    line1           TEXT NOT NULL,
    subcity         TEXT,
    woreda          TEXT,
    city            TEXT NOT NULL DEFAULT 'Addis Ababa',
    landmark        TEXT,                       -- landmarks matter more than street numbers locally
    lat             NUMERIC(9,6),
    lng             NUMERIC(9,6),
    is_default      BOOLEAN NOT NULL DEFAULT FALSE,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX one_default_address ON identity.addresses (user_id) WHERE is_default;

-- Account limits per KYC level, set by compliance (values are configuration, not code)
CREATE TABLE identity.kyc_limits (
    level               identity.kyc_level NOT NULL,
    currency            platform.currency NOT NULL,
    max_balance_minor   BIGINT NOT NULL,
    daily_out_minor     BIGINT NOT NULL,
    monthly_out_minor   BIGINT NOT NULL,
    PRIMARY KEY (level, currency)
);

-- ---------------------------------------------------------------------------
-- LEDGER: double-entry, append-only
-- ---------------------------------------------------------------------------
CREATE TYPE ledger.account_kind AS ENUM (
    'user_wallet',          -- liability: what we owe a user (mirrors funds held at the partner)
    'merchant_settlement',  -- liability: owed to a merchant, paid out on schedule
    'partner_clearing',     -- asset: in transit at a rail (Telebirr, EthSwitch, card issuer, remittance)
    'fee_revenue',          -- income
    'commission_revenue',   -- income
    'rewards_liability',    -- points redeemable for money
    'suspense',             -- unmatched items awaiting reconciliation
    'hold',                 -- funds frozen by risk or a pending authorisation
    'order_escrow'          -- liability: paid for orders not yet handed over (released to the shop or refunded)
);

CREATE TABLE ledger.accounts (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    kind            ledger.account_kind NOT NULL,
    owner_type      TEXT NOT NULL CHECK (owner_type IN ('user', 'merchant', 'partner', 'platform')),
    owner_id        UUID,                       -- null for platform accounts
    currency        platform.currency NOT NULL,
    normal_side     CHAR(1) NOT NULL CHECK (normal_side IN ('D', 'C')),
    allow_negative  BOOLEAN NOT NULL DEFAULT FALSE,
    status          TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'frozen', 'closed')),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE NULLS NOT DISTINCT (kind, owner_type, owner_id, currency)  -- platform accounts have no owner_id
);

CREATE TABLE ledger.journal_entries (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    kind            TEXT NOT NULL,              -- p2p_transfer, qr_payment, bill_payment, payout, refund, fee, fx_conversion, reversal
    source_type     TEXT NOT NULL,              -- payments.intent, commerce.order, recon.adjustment ...
    source_id       UUID NOT NULL,
    reverses_id     UUID REFERENCES ledger.journal_entries(id),
    effective_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (source_type, source_id, kind)       -- one entry per business event: retries cannot double-post
);

CREATE TABLE ledger.postings (
    id              BIGSERIAL,
    entry_id        UUID NOT NULL REFERENCES ledger.journal_entries(id),
    account_id      UUID NOT NULL REFERENCES ledger.accounts(id),
    side            CHAR(1) NOT NULL CHECK (side IN ('D', 'C')),
    amount_minor    BIGINT NOT NULL CHECK (amount_minor > 0),
    currency        platform.currency NOT NULL,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (id, created_at)
) PARTITION BY RANGE (created_at);
CREATE TABLE ledger.postings_2026_11 PARTITION OF ledger.postings FOR VALUES FROM ('2026-11-01') TO ('2026-12-01');
CREATE TABLE ledger.postings_2026_12 PARTITION OF ledger.postings FOR VALUES FROM ('2026-12-01') TO ('2027-01-01');
CREATE TABLE ledger.postings_default PARTITION OF ledger.postings DEFAULT;  -- safety net if a month wasn't created in time
CREATE INDEX ON ledger.postings (account_id, created_at DESC);
CREATE INDEX ON ledger.postings (entry_id);

-- Balance cache, updated in the same transaction as the postings. The postings stay the source of truth.
CREATE TABLE ledger.balances (
    account_id      UUID PRIMARY KEY REFERENCES ledger.accounts(id),
    balance_minor   BIGINT NOT NULL DEFAULT 0,  -- in the account's normal direction
    version         BIGINT NOT NULL DEFAULT 0,  -- optimistic lock
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Every journal entry must balance per currency. Checked at commit, after all postings are written.
CREATE FUNCTION ledger.assert_entry_balanced() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE bad RECORD;
BEGIN
    SELECT currency,
           SUM(CASE WHEN side = 'D' THEN amount_minor ELSE -amount_minor END) AS net
      INTO bad
      FROM ledger.postings
     WHERE entry_id = NEW.entry_id
     GROUP BY currency
    HAVING SUM(CASE WHEN side = 'D' THEN amount_minor ELSE -amount_minor END) <> 0
     LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'journal entry % is unbalanced in % by %', NEW.entry_id, bad.currency, bad.net;
    END IF;
    RETURN NULL;
END $$;

CREATE CONSTRAINT TRIGGER postings_balanced
    AFTER INSERT ON ledger.postings
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION ledger.assert_entry_balanced();

-- Append-only: postings and entries are never updated or deleted. Corrections are reversal entries.
CREATE FUNCTION ledger.forbid_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'ledger rows are append-only; post a reversal instead';
END $$;
CREATE TRIGGER postings_append_only BEFORE UPDATE OR DELETE ON ledger.postings
    FOR EACH ROW EXECUTE FUNCTION ledger.forbid_mutation();
CREATE TRIGGER entries_append_only BEFORE UPDATE OR DELETE ON ledger.journal_entries
    FOR EACH ROW EXECUTE FUNCTION ledger.forbid_mutation();

-- ---------------------------------------------------------------------------
-- PAYMENTS: funding sources, payment intents, transfers, FX, QR
-- ---------------------------------------------------------------------------
-- 'sandbox' is test money in dev environments only (POST /v1/sandbox/topups). It never names a real
-- provider, so test credits can't be mistaken for partner payments in activity or reconciliation.
CREATE TYPE payments.rail AS ENUM ('wallet', 'telebirr', 'cbe_birr', 'mpesa_et', 'ethswitch', 'card', 'remittance', 'sandbox');
CREATE TYPE payments.intent_status AS ENUM (
    'created', 'requires_confirmation', 'processing', 'held_for_review',
    'succeeded', 'failed', 'cancelled', 'reversed'
);

CREATE TABLE payments.funding_sources (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id         UUID NOT NULL REFERENCES identity.users(id),
    rail            payments.rail NOT NULL,
    label           TEXT NOT NULL,              -- "CBE ••8812"
    partner_token   TEXT NOT NULL,              -- partner's token for the account; never a PAN or full account number
    last4           CHAR(4),
    currency        platform.currency NOT NULL,
    status          TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('pending', 'active', 'removed')),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE payments.intents (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    kind                TEXT NOT NULL CHECK (kind IN ('p2p', 'qr_merchant', 'bill', 'airtime', 'order', 'remittance_out', 'remittance_in', 'topup', 'withdrawal', 'miniapp')),
    payer_user_id       UUID REFERENCES identity.users(id),
    payee_type          TEXT NOT NULL CHECK (payee_type IN ('user', 'merchant', 'biller', 'external')),
    payee_id            UUID,
    payee_external_ref  TEXT,                   -- bank account token, phone for non-users, biller account
    amount_minor        BIGINT NOT NULL CHECK (amount_minor > 0),
    currency            platform.currency NOT NULL,
    fee_minor           BIGINT NOT NULL DEFAULT 0 CHECK (fee_minor >= 0),
    funding_source_id   UUID REFERENCES payments.funding_sources(id),  -- null = wallet balance
    rail                payments.rail NOT NULL,
    status              payments.intent_status NOT NULL DEFAULT 'created',
    failure_code        TEXT,
    risk_score          NUMERIC(4,3),
    fx_quote_id         UUID,
    order_id            UUID,                   -- commerce.orders, when kind = 'order'
    miniapp_id          UUID,                   -- miniapp.apps, when kind = 'miniapp'
    note                TEXT CHECK (char_length(note) <= 140),
    partner_ref         TEXT,                   -- rail's transaction reference, for reconciliation
    confirmed_at        TIMESTAMPTZ,
    completed_at        TIMESTAMPTZ,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX ON payments.intents (payer_user_id, created_at DESC);
CREATE INDEX ON payments.intents (payee_type, payee_id, created_at DESC);
CREATE INDEX ON payments.intents (status) WHERE status IN ('processing', 'held_for_review');
CREATE UNIQUE INDEX ON payments.intents (rail, partner_ref) WHERE partner_ref IS NOT NULL;

CREATE TABLE payments.intent_events (
    id              BIGSERIAL PRIMARY KEY,
    intent_id       UUID NOT NULL REFERENCES payments.intents(id),
    from_status     payments.intent_status,
    to_status       payments.intent_status NOT NULL,
    reason          TEXT,
    actor           TEXT NOT NULL,              -- system, user:<id>, staff:<id>, partner:<rail>
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE payments.fx_quotes (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id         UUID NOT NULL REFERENCES identity.users(id),
    sell_currency   platform.currency NOT NULL,
    buy_currency    platform.currency NOT NULL,
    sell_minor      BIGINT NOT NULL,
    buy_minor       BIGINT NOT NULL,
    rate            NUMERIC(18,8) NOT NULL,     -- buy per sell, including spread
    spread_bps      INTEGER NOT NULL,
    provider        TEXT NOT NULL,              -- licensed FX or remittance partner
    expires_at      TIMESTAMPTZ NOT NULL,
    used_at         TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE payments.qr_codes (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    owner_type      TEXT NOT NULL CHECK (owner_type IN ('user', 'merchant', 'branch', 'till')),
    owner_id        UUID NOT NULL,
    mode            TEXT NOT NULL CHECK (mode IN ('static', 'dynamic')),
    amount_minor    BIGINT,                     -- dynamic codes only
    currency        platform.currency NOT NULL DEFAULT 'ETB',
    payload         TEXT NOT NULL UNIQUE,       -- EMVCo merchant-presented QR string, interoperable with other wallets
    expires_at      TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------------
-- BILLS
-- ---------------------------------------------------------------------------
CREATE TABLE bills.billers (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    code            TEXT NOT NULL UNIQUE,       -- eeu_prepaid, aawsa, ethiotel_fiber
    name            JSONB NOT NULL,             -- {"en": "...", "am": "..."}
    category        TEXT NOT NULL CHECK (category IN ('electricity', 'water', 'internet', 'tv', 'telecom', 'education', 'government', 'insurance')),
    aggregator      TEXT NOT NULL,              -- integration partner
    account_regex   TEXT NOT NULL,
    supports_lookup BOOLEAN NOT NULL DEFAULT TRUE,
    fee_minor       BIGINT NOT NULL DEFAULT 0,
    active          BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE bills.saved_billers (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id         UUID NOT NULL REFERENCES identity.users(id),
    biller_id       UUID NOT NULL REFERENCES bills.billers(id),
    account_ref     TEXT NOT NULL,
    nickname        TEXT,
    autopay         BOOLEAN NOT NULL DEFAULT FALSE,
    autopay_max_minor BIGINT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (user_id, biller_id, account_ref)
);

CREATE TABLE bills.statements (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    saved_biller_id UUID NOT NULL REFERENCES bills.saved_billers(id),
    amount_minor    BIGINT NOT NULL,
    currency        platform.currency NOT NULL DEFAULT 'ETB',
    due_date        DATE,
    status          TEXT NOT NULL CHECK (status IN ('due', 'paid', 'overdue', 'cancelled')),
    payment_intent_id UUID REFERENCES payments.intents(id),
    biller_ref      TEXT,
    fetched_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX ON bills.statements (due_date) WHERE status = 'due';

-- ---------------------------------------------------------------------------
-- MERCHANTS
-- ---------------------------------------------------------------------------
CREATE TABLE merchant.merchants (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    legal_name          TEXT NOT NULL,
    trade_name          TEXT NOT NULL,
    tin                 TEXT,                   -- Ethiopian taxpayer ID; unique among merchants that aren't closed
    business_licence    TEXT,
    category_code       TEXT NOT NULL,          -- MCC-style category
    tier                TEXT NOT NULL DEFAULT 'micro' CHECK (tier IN ('micro', 'sme', 'enterprise')),
    plan                TEXT NOT NULL DEFAULT 'free' CHECK (plan IN ('free', 'pro')),
    status              TEXT NOT NULL DEFAULT 'applied' CHECK (status IN ('applied', 'kyb_review', 'active', 'suspended', 'closed')),
    payout_schedule     TEXT NOT NULL DEFAULT 'daily' CHECK (payout_schedule IN ('instant', 'daily', 'weekly')),
    merchant_no         TEXT UNIQUE CHECK (merchant_no ~ '^[0-9]{8}$'),  -- given on approval; printed on the shop's QR
    city                TEXT,
    applied_by          UUID REFERENCES identity.users(id),
    decision_note       TEXT,                   -- why operations rejected, suspended or reinstated it (shown to the owner)
    approved_by         UUID,
    approved_at         TIMESTAMPTZ,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX merchants_tin_open ON merchant.merchants (tin) WHERE status <> 'closed';

CREATE TABLE merchant.branches (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    merchant_id     UUID NOT NULL REFERENCES merchant.merchants(id),
    name            TEXT NOT NULL,
    address         TEXT,
    lat             NUMERIC(9,6),
    lng             NUMERIC(9,6),
    accepting_orders BOOLEAN NOT NULL DEFAULT TRUE,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE merchant.members (
    merchant_id     UUID NOT NULL REFERENCES merchant.merchants(id),
    user_id         UUID NOT NULL REFERENCES identity.users(id),
    role            TEXT NOT NULL CHECK (role IN ('owner', 'manager', 'cashier', 'accountant')),
    branch_id       UUID REFERENCES merchant.branches(id),  -- null = all branches
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (merchant_id, user_id)
);

-- Joining a shop's team. An owner invites a phone number with a role; the person accepts in the app, so
-- nobody is added to a business without agreeing. The invitation waits for numbers not yet on EDash and
-- is matched when they sign up. Owners aren't invited this way: ownership changes go through KYB.
CREATE TABLE merchant.invitations (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    merchant_id     UUID NOT NULL REFERENCES merchant.merchants(id),
    phone_e164      TEXT NOT NULL CHECK (phone_e164 ~ '^\+[1-9][0-9]{7,14}$'),
    role            TEXT NOT NULL CHECK (role IN ('manager', 'cashier', 'accountant')),
    invited_by      UUID NOT NULL REFERENCES identity.users(id),
    status          TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'accepted', 'declined', 'cancelled')),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at      TIMESTAMPTZ NOT NULL,             -- a pending invitation past this is treated as expired
    answered_at     TIMESTAMPTZ,
    answered_by     UUID REFERENCES identity.users(id),
    CHECK ((status = 'pending') = (answered_at IS NULL))
);
CREATE UNIQUE INDEX ON merchant.invitations (merchant_id, phone_e164) WHERE status = 'pending';
CREATE INDEX ON merchant.invitations (phone_e164) WHERE status = 'pending';

-- Signing in to the web business console. The browser shows a one-time code; a member of the shop types
-- it into the app and approves it with their PIN, which binds the browser to that person and that shop.
-- Only hashes of the code and of the browser's secret are kept.
CREATE TABLE merchant.web_logins (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    secret_hash     TEXT NOT NULL UNIQUE,       -- sha256 of the secret in the browser's sign-in cookie
    code_hash       TEXT NOT NULL UNIQUE,       -- sha256 of the code shown in the browser
    ip              INET,
    user_agent      TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at      TIMESTAMPTZ NOT NULL,
    approved_by     UUID REFERENCES identity.users(id),
    merchant_id     UUID REFERENCES merchant.merchants(id),
    approved_at     TIMESTAMPTZ,
    used_at         TIMESTAMPTZ,                -- the browser picked up its session
    CHECK ((approved_by IS NULL) = (approved_at IS NULL) AND (approved_by IS NULL) = (merchant_id IS NULL))
);
CREATE INDEX ON merchant.web_logins (expires_at);

CREATE TABLE merchant.web_sessions (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    token_hash      TEXT NOT NULL UNIQUE,       -- sha256 of the session cookie
    user_id         UUID NOT NULL REFERENCES identity.users(id),
    merchant_id     UUID NOT NULL REFERENCES merchant.merchants(id),
    csrf_token      TEXT NOT NULL,
    ip              INET,
    user_agent      TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_seen_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at      TIMESTAMPTZ NOT NULL,
    revoked_at      TIMESTAMPTZ
);
CREATE INDEX ON merchant.web_sessions (user_id, merchant_id);

-- KYB documents. The files live encrypted (AES-256-GCM, by the application) in object storage under
-- object_key; this table holds what staff need to find, check and decide them. No personal data in keys.
CREATE TABLE merchant.documents (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    merchant_id     UUID NOT NULL REFERENCES merchant.merchants(id),
    kind            TEXT NOT NULL CHECK (kind IN ('tin_certificate', 'trade_licence', 'owner_id', 'other')),
    content_type    TEXT NOT NULL CHECK (content_type IN ('image/jpeg', 'image/png', 'application/pdf')),
    size_bytes      INTEGER NOT NULL CHECK (size_bytes > 0),
    sha256          TEXT NOT NULL CHECK (sha256 ~ '^[0-9a-f]{64}$'),
    object_key      TEXT NOT NULL UNIQUE,
    key_id          TEXT NOT NULL,              -- which encryption key sealed it, for key rotation
    status          TEXT NOT NULL DEFAULT 'submitted' CHECK (status IN ('submitted', 'accepted', 'rejected', 'replaced')),
    uploaded_by     UUID NOT NULL REFERENCES identity.users(id),
    uploaded_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    reviewed_by     UUID,                       -- admin.staff (defined later)
    reviewed_at     TIMESTAMPTZ,
    review_note     TEXT,                       -- why it was rejected (shown to the owner)
    CHECK (status NOT IN ('accepted', 'rejected') OR reviewed_by IS NOT NULL)
);

CREATE INDEX documents_merchant ON merchant.documents (merchant_id, kind, uploaded_at DESC);
CREATE UNIQUE INDEX documents_same_file ON merchant.documents (merchant_id, sha256) WHERE status <> 'replaced';

CREATE TABLE merchant.commission_plans (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    merchant_id     UUID REFERENCES merchant.merchants(id),  -- null = default for a category
    category_code   TEXT,
    channel         TEXT NOT NULL CHECK (channel IN ('qr', 'marketplace', 'delivery', 'miniapp')),
    rate_bps        INTEGER NOT NULL CHECK (rate_bps BETWEEN 0 AND 5000),
    fixed_minor     BIGINT NOT NULL DEFAULT 0,
    valid_from      TIMESTAMPTZ NOT NULL,
    valid_to        TIMESTAMPTZ,
    approved_by     UUID NOT NULL,              -- maker-checker: admin.approvals
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Where a merchant's payouts go. Changing it is the classic account-takeover move, so only an owner can,
-- with their PIN, and payouts to a destination younger than the cooling-off period are held for review.
CREATE TABLE merchant.payout_destinations (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    merchant_id     UUID NOT NULL REFERENCES merchant.merchants(id),
    rail            payments.rail NOT NULL CHECK (rail IN ('telebirr', 'cbe_birr', 'mpesa_et', 'ethswitch')),
    bank_code       TEXT,                   -- EthSwitch participant code; null for mobile money
    account_ref     TEXT NOT NULL,          -- wallet number or bank account; to move under envelope encryption with the other PII
    label           TEXT NOT NULL,          -- "telebirr ••4567", "CBE ••8812"
    created_by      UUID NOT NULL REFERENCES identity.users(id),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    replaced_at     TIMESTAMPTZ             -- set when a newer destination takes over
);
CREATE UNIQUE INDEX ON merchant.payout_destinations (merchant_id) WHERE replaced_at IS NULL;

CREATE TABLE merchant.payouts (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    merchant_id     UUID NOT NULL REFERENCES merchant.merchants(id),
    period_start    TIMESTAMPTZ NOT NULL,
    period_end      TIMESTAMPTZ NOT NULL,
    gross_minor     BIGINT NOT NULL,
    commission_minor BIGINT NOT NULL,
    fees_minor      BIGINT NOT NULL,
    refunds_minor   BIGINT NOT NULL,
    net_minor       BIGINT NOT NULL CHECK (net_minor > 0),
    currency        platform.currency NOT NULL DEFAULT 'ETB',
    status          TEXT NOT NULL CHECK (status IN ('scheduled', 'sent', 'settled', 'failed', 'on_hold')),
    hold_reason     TEXT,                   -- why on_hold: new_destination, merchant_suspended, no_destination, rejected_by_partner
    destination_id  UUID REFERENCES merchant.payout_destinations(id),
    rail            payments.rail,
    partner_ref     TEXT,
    attempts        INTEGER NOT NULL DEFAULT 0,
    attempt_base    INTEGER NOT NULL DEFAULT 0,  -- attempts when staff last released it; failures count from here
    last_error      TEXT,                   -- e.g. rail_unavailable while no licensed payout partner is configured
    scheduled_for   TIMESTAMPTZ NOT NULL,
    sent_at         TIMESTAMPTZ,
    settled_at      TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (net_minor = gross_minor - commission_minor - fees_minor - refunds_minor)
);
CREATE INDEX ON merchant.payouts (merchant_id, created_at DESC, id DESC);
CREATE INDEX ON merchant.payouts (status) WHERE status IN ('scheduled', 'sent');

-- The ledger entries each payout covers. An entry is paid out once (primary key).
CREATE TABLE merchant.payout_items (
    entry_id        UUID PRIMARY KEY REFERENCES ledger.journal_entries(id),
    payout_id       UUID NOT NULL REFERENCES merchant.payouts(id),
    gross_minor     BIGINT NOT NULL,
    commission_minor BIGINT NOT NULL,
    net_minor       BIGINT NOT NULL
);
CREATE INDEX ON merchant.payout_items (payout_id);

-- ---------------------------------------------------------------------------
-- COMMERCE (Phase 2): catalog, carts, orders
-- ---------------------------------------------------------------------------
-- A shop's ordering settings. A merchant sells in the app once it has a row here with open = TRUE.
CREATE TABLE commerce.shops (
    merchant_id     UUID PRIMARY KEY REFERENCES merchant.merchants(id),
    open            BOOLEAN NOT NULL DEFAULT FALSE,      -- taking orders now
    pickup          BOOLEAN NOT NULL DEFAULT TRUE,
    delivery        BOOLEAN NOT NULL DEFAULT FALSE,      -- the shop delivers itself (no courier network yet)
    delivery_fee_minor BIGINT NOT NULL DEFAULT 0 CHECK (delivery_fee_minor >= 0),
    delivery_area   TEXT CHECK (char_length(delivery_area) <= 200),
    about           TEXT CHECK (char_length(about) <= 500),
    -- Delivery times (all null: the shop delivers as soon as it can). Minutes after midnight, Ethiopian time.
    slot_minutes    SMALLINT CHECK (slot_minutes IN (60, 120, 180, 240)),
    slot_from       SMALLINT CHECK (slot_from BETWEEN 0 AND 1440),
    slot_to         SMALLINT CHECK (slot_to BETWEEN 0 AND 1440),
    slot_capacity   SMALLINT CHECK (slot_capacity BETWEEN 1 AND 50),
    slot_days       SMALLINT CHECK (slot_days BETWEEN 1 AND 7),
    slot_lead_minutes SMALLINT CHECK (slot_lead_minutes BETWEEN 0 AND 1440),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (pickup OR delivery),
    CHECK ((slot_minutes IS NULL) = (slot_from IS NULL) AND (slot_minutes IS NULL) = (slot_to IS NULL)
       AND (slot_minutes IS NULL) = (slot_capacity IS NULL) AND (slot_minutes IS NULL) = (slot_days IS NULL)
       AND (slot_minutes IS NULL) = (slot_lead_minutes IS NULL)),
    CHECK (slot_to - slot_from >= slot_minutes)
);

CREATE TABLE commerce.products (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    merchant_id     UUID NOT NULL REFERENCES merchant.merchants(id),
    title           TEXT NOT NULL CHECK (char_length(title) BETWEEN 1 AND 80),   -- in the shop's own words
    description     TEXT CHECK (char_length(description) <= 500),
    category        TEXT NOT NULL DEFAULT '' CHECK (char_length(category) <= 40), -- the shop's own shelf name
    price_minor     BIGINT NOT NULL CHECK (price_minor > 0),
    currency        platform.currency NOT NULL DEFAULT 'ETB',
    stock           INTEGER CHECK (stock >= 0),                    -- null: not counted
    images          TEXT[] NOT NULL DEFAULT '{}',
    status          TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'hidden', 'archived')),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX ON commerce.products (merchant_id, status);

CREATE SEQUENCE commerce.order_number_seq START 100001;

-- Lifecycle: pending_payment -> placed (paid; the money waits in order escrow) -> accepted -> ready
-- (pickup: ready to collect; delivery: packed) -> on_the_way (delivery) -> delivered (handed over:
-- escrow pays the shop). cancelled at any point before delivered; anything paid is refunded.
CREATE TABLE commerce.orders (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    number          TEXT NOT NULL UNIQUE DEFAULT 'OR-' || nextval('commerce.order_number_seq'),
    user_id         UUID NOT NULL REFERENCES identity.users(id),
    merchant_id     UUID NOT NULL REFERENCES merchant.merchants(id),
    branch_id       UUID REFERENCES merchant.branches(id),          -- null: the shop's only location
    channel         TEXT NOT NULL CHECK (channel IN ('delivery', 'pickup', 'in_store')),
    status          TEXT NOT NULL CHECK (status IN ('pending_payment', 'placed', 'accepted', 'packing', 'ready', 'on_the_way', 'delivered', 'cancelled', 'refunded')),
    subtotal_minor  BIGINT NOT NULL,
    delivery_fee_minor BIGINT NOT NULL DEFAULT 0,
    discount_minor  BIGINT NOT NULL DEFAULT 0,
    points_used     INTEGER NOT NULL DEFAULT 0,
    total_minor     BIGINT NOT NULL CHECK (total_minor > 0),
    currency        platform.currency NOT NULL DEFAULT 'ETB',
    address_id      UUID REFERENCES identity.addresses(id),
    delivery_address TEXT CHECK (char_length(delivery_address) <= 300),  -- as written at checkout
    note            TEXT CHECK (char_length(note) <= 280),
    intent_id       UUID,                                         -- payments.intents paying for it
    handover_code   TEXT CHECK (handover_code ~ '^[0-9]{4}$'),    -- the customer shows it to collect; only they see it
    handover_tries  SMALLINT NOT NULL DEFAULT 0,
    cancel_reason   TEXT,                                         -- customer_cancelled, shop_declined, shop_cancelled, no_response, payment_failed, payment_not_finished
    cancel_note     TEXT CHECK (char_length(cancel_note) <= 280),  -- the shop's words to the customer
    slot_start      TIMESTAMPTZ,
    slot_end        TIMESTAMPTZ,
    gift_from_user_id UUID REFERENCES identity.users(id),  -- diaspora "send a basket home"
    placed_at       TIMESTAMPTZ,
    accepted_at     TIMESTAMPTZ,
    ready_at        TIMESTAMPTZ,
    completed_at    TIMESTAMPTZ,
    cancelled_at    TIMESTAMPTZ,
    overdue_at      TIMESTAMPTZ,   -- accepted but not handed over in time: the shop and customer were reminded
    review_at       TIMESTAMPTZ,   -- still not handed over later: passed to operations, who refund or pay the shop
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (channel <> 'delivery' OR delivery_address IS NOT NULL)
);
CREATE INDEX ON commerce.orders (merchant_id, status, created_at DESC);
CREATE INDEX ON commerce.orders (user_id, created_at DESC);
CREATE INDEX ON commerce.orders (status, created_at) WHERE status IN ('pending_payment', 'placed');
CREATE INDEX ON commerce.orders (accepted_at) WHERE status IN ('accepted', 'ready', 'on_the_way');
CREATE INDEX ON commerce.orders (merchant_id, slot_start) WHERE slot_start IS NOT NULL;

CREATE TABLE commerce.order_items (
    order_id        UUID NOT NULL REFERENCES commerce.orders(id),
    line_no         SMALLINT NOT NULL,
    product_id      UUID NOT NULL REFERENCES commerce.products(id),
    title_snapshot  TEXT NOT NULL,
    unit_price_minor BIGINT NOT NULL,
    quantity        INTEGER NOT NULL CHECK (quantity BETWEEN 1 AND 99),
    substitution_of SMALLINT,                   -- line replaced with the customer's approval
    PRIMARY KEY (order_id, line_no)
);

CREATE TABLE commerce.reviews (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    order_id        UUID NOT NULL UNIQUE REFERENCES commerce.orders(id),
    rating          SMALLINT NOT NULL CHECK (rating BETWEEN 1 AND 5),
    body            TEXT,
    merchant_reply  TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------------
-- DELIVERY (Phase 3)
-- ---------------------------------------------------------------------------
CREATE TABLE delivery.couriers (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id         UUID NOT NULL UNIQUE REFERENCES identity.users(id),
    vehicle         TEXT NOT NULL CHECK (vehicle IN ('motorbike', 'bicycle', 'car', 'foot')),
    fleet_partner   TEXT,                       -- null = own fleet
    status          TEXT NOT NULL DEFAULT 'offline' CHECK (status IN ('offline', 'available', 'busy', 'suspended')),
    rating          NUMERIC(3,2)
);

CREATE TABLE delivery.jobs (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    order_id        UUID UNIQUE REFERENCES commerce.orders(id),
    courier_id      UUID REFERENCES delivery.couriers(id),
    status          TEXT NOT NULL CHECK (status IN ('searching', 'assigned', 'picked_up', 'delivered', 'failed', 'cancelled')),
    pickup_eta      TIMESTAMPTZ,
    dropoff_eta     TIMESTAMPTZ,
    proof_code_hash TEXT,                       -- customer's 4-digit handover code
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
-- Live courier positions go to a time-series store (Redis geo + warehouse), not this database.

-- ---------------------------------------------------------------------------
-- REWARDS (Phase 4)
-- ---------------------------------------------------------------------------
CREATE TABLE rewards.point_events (
    id              BIGSERIAL PRIMARY KEY,
    user_id         UUID NOT NULL REFERENCES identity.users(id),
    delta           INTEGER NOT NULL,
    reason          TEXT NOT NULL CHECK (reason IN ('earn_payment', 'earn_campaign', 'redeem', 'expire', 'adjust')),
    source_type     TEXT NOT NULL,
    source_id       UUID NOT NULL,
    campaign_id     UUID,
    expires_at      TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (source_type, source_id, reason)
);

CREATE TABLE rewards.subscriptions (
    user_id         UUID PRIMARY KEY REFERENCES identity.users(id),
    plan            TEXT NOT NULL CHECK (plan IN ('plus_monthly', 'plus_annual')),
    status          TEXT NOT NULL CHECK (status IN ('trial', 'active', 'past_due', 'cancelled')),
    current_period_end TIMESTAMPTZ NOT NULL,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE rewards.campaigns (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name            TEXT NOT NULL,
    funded_by       TEXT NOT NULL CHECK (funded_by IN ('platform', 'merchant', 'partner')),
    merchant_id     UUID REFERENCES merchant.merchants(id),
    rule            JSONB NOT NULL,             -- e.g. {"multiplier": 2, "channel": "qr"}
    budget_minor    BIGINT,
    starts_at       TIMESTAMPTZ NOT NULL,
    ends_at         TIMESTAMPTZ NOT NULL,
    status          TEXT NOT NULL CHECK (status IN ('draft', 'pending_approval', 'live', 'ended')),
    created_by      UUID NOT NULL,
    approved_by     UUID
);

-- ---------------------------------------------------------------------------
-- MINI-APPS (Phase 4)
-- ---------------------------------------------------------------------------
CREATE TABLE miniapp.developers (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    merchant_id     UUID REFERENCES merchant.merchants(id),
    name            TEXT NOT NULL,
    contact_email   CITEXT NOT NULL,
    status          TEXT NOT NULL CHECK (status IN ('applied', 'verified', 'suspended')),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE miniapp.apps (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    developer_id    UUID NOT NULL REFERENCES miniapp.developers(id),
    slug            TEXT NOT NULL UNIQUE,
    name            JSONB NOT NULL,
    category        TEXT NOT NULL,
    revenue_share_bps INTEGER NOT NULL DEFAULT 700,
    status          TEXT NOT NULL CHECK (status IN ('draft', 'in_review', 'live', 'suspended')),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE miniapp.versions (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    app_id          UUID NOT NULL REFERENCES miniapp.apps(id),
    version         TEXT NOT NULL,
    bundle_sha256   TEXT NOT NULL,
    manifest        JSONB NOT NULL,             -- signed: requested scopes, allowed domains, entry point
    review_status   TEXT NOT NULL CHECK (review_status IN ('submitted', 'approved', 'rejected')),
    reviewed_by     UUID,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (app_id, version)
);

CREATE TABLE miniapp.grants (
    user_id         UUID NOT NULL REFERENCES identity.users(id),
    app_id          UUID NOT NULL REFERENCES miniapp.apps(id),
    scope           TEXT NOT NULL CHECK (scope IN ('profile.basic', 'phone', 'location', 'payments.request', 'addresses')),
    granted_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    revoked_at      TIMESTAMPTZ,
    PRIMARY KEY (user_id, app_id, scope)
);

-- ---------------------------------------------------------------------------
-- RISK
-- ---------------------------------------------------------------------------
CREATE TABLE risk.decisions (
    intent_id       UUID PRIMARY KEY REFERENCES payments.intents(id),
    score           NUMERIC(4,3) NOT NULL,
    model_version   TEXT NOT NULL,
    rules_hit       TEXT[] NOT NULL DEFAULT '{}',
    action          TEXT NOT NULL CHECK (action IN ('allow', 'step_up', 'hold', 'block')),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE SEQUENCE risk.case_number_seq START 20001;

-- A case opens when a payment is held for review. Further held payments from the same person join their
-- open case. Staff work it in the operations console.
-- Phone numbers looked up by starting a transfer (payee_phone), which shows the recipient's name. Counted
-- per account and per phone to stop people harvesting who has an account (payments/lookups.go). Kept 48 h.
CREATE TABLE payments.payee_lookups (
    id              BIGSERIAL PRIMARY KEY,
    user_id         UUID NOT NULL REFERENCES identity.users(id),
    device_id       UUID,
    number_hash     TEXT NOT NULL,              -- SHA-256 of the number; only distinct numbers count
    found           BOOLEAN NOT NULL,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX ON payments.payee_lookups (user_id, created_at);
CREATE INDEX ON payments.payee_lookups (device_id, created_at) WHERE device_id IS NOT NULL;

CREATE TABLE risk.cases (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    number          TEXT NOT NULL UNIQUE DEFAULT 'FR-' || nextval('risk.case_number_seq'),
    subject_type    TEXT NOT NULL CHECK (subject_type IN ('user', 'merchant', 'device')),
    subject_id      UUID NOT NULL,
    summary         TEXT NOT NULL,
    risk_score      SMALLINT NOT NULL CHECK (risk_score BETWEEN 0 AND 100),
    amount_minor    BIGINT,
    currency        platform.currency,
    status          TEXT NOT NULL CHECK (status IN ('unassigned', 'in_review', 'awaiting_approval', 'resolved', 'escalated_aml')),
    assignee_id     UUID,
    sla_due_at      TIMESTAMPTZ NOT NULL,
    resolution      TEXT,                       -- how it ended (internal; never shown to the customer)
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX ON risk.cases (status, risk_score DESC);
CREATE UNIQUE INDEX cases_one_open ON risk.cases (subject_type, subject_id) WHERE status NOT IN ('resolved', 'escalated_aml');

CREATE TABLE risk.case_notes (
    id              BIGSERIAL PRIMARY KEY,
    case_id         UUID NOT NULL REFERENCES risk.cases(id),
    staff_id        UUID NOT NULL,              -- admin.staff (defined later)
    body            TEXT NOT NULL CHECK (length(body) BETWEEN 1 AND 4000),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX ON risk.case_notes (case_id, id);

CREATE TABLE risk.case_intents (
    case_id         UUID NOT NULL REFERENCES risk.cases(id),
    intent_id       UUID NOT NULL REFERENCES payments.intents(id),
    PRIMARY KEY (case_id, intent_id)
);

-- ---------------------------------------------------------------------------
-- RECONCILIATION
-- ---------------------------------------------------------------------------
CREATE TABLE recon.partner_statements (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    rail            payments.rail NOT NULL,
    business_date   DATE NOT NULL,
    file_sha256     TEXT NOT NULL UNIQUE,
    line_count      INTEGER NOT NULL,
    imported_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (rail, business_date)
);

CREATE TABLE recon.statement_lines (
    id              BIGSERIAL PRIMARY KEY,
    statement_id    UUID NOT NULL REFERENCES recon.partner_statements(id),
    partner_ref     TEXT NOT NULL,
    amount_minor    BIGINT NOT NULL,
    currency        platform.currency NOT NULL,
    occurred_at     TIMESTAMPTZ NOT NULL,
    matched_intent_id UUID REFERENCES payments.intents(id),
    match_status    TEXT NOT NULL DEFAULT 'unmatched' CHECK (match_status IN ('matched', 'unmatched', 'amount_mismatch', 'missing_internal', 'resolved')),
    resolved_by     UUID,
    resolution_note TEXT
);
CREATE INDEX ON recon.statement_lines (match_status) WHERE match_status <> 'matched';

-- ---------------------------------------------------------------------------
-- ADMIN: staff, RBAC, maker-checker approvals, audit log
-- ---------------------------------------------------------------------------
CREATE TABLE admin.staff (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    email           CITEXT NOT NULL UNIQUE,
    full_name       TEXT NOT NULL,
    sso_subject     TEXT NOT NULL UNIQUE,       -- staff sign in through the company IdP with hardware MFA
    status          TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended', 'left')),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE admin.roles (
    id              TEXT PRIMARY KEY,           -- super_admin, finance_officer, risk_analyst, support_agent, merchant_ops, content_editor
    name            TEXT NOT NULL,
    description     TEXT
);

-- grant = 'full' (act alone), 'approve' (needs a second person), 'view' (read, masked)
CREATE TABLE admin.role_permissions (
    role_id         TEXT NOT NULL REFERENCES admin.roles(id),
    permission      TEXT NOT NULL,              -- transactions.view, refunds.small, refunds.large, accounts.freeze ...
    grant_level     TEXT NOT NULL CHECK (grant_level IN ('full', 'approve', 'view')),
    PRIMARY KEY (role_id, permission)
);

CREATE TABLE admin.staff_roles (
    staff_id        UUID NOT NULL REFERENCES admin.staff(id),
    role_id         TEXT NOT NULL REFERENCES admin.roles(id),
    granted_by      UUID NOT NULL REFERENCES admin.staff(id),
    granted_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (staff_id, role_id),
    CHECK (granted_by <> staff_id)
);

CREATE TABLE admin.approvals (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    permission      TEXT NOT NULL,
    target_type     TEXT NOT NULL,
    target_id       UUID NOT NULL,
    payload         JSONB NOT NULL,             -- the exact change requested
    requested_by    UUID NOT NULL REFERENCES admin.staff(id),
    requested_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    decided_by      UUID REFERENCES admin.staff(id),
    decision        TEXT CHECK (decision IN ('approved', 'rejected')),
    decided_at      TIMESTAMPTZ,
    expires_at      TIMESTAMPTZ NOT NULL,
    request_note    TEXT NOT NULL,              -- why the maker asks for it
    decision_note   TEXT,
    CHECK (decided_by IS NULL OR decided_by <> requested_by)   -- nobody approves their own request
);
CREATE INDEX ON admin.approvals (requested_at) WHERE decision IS NULL;

-- Who staff are signed in as on the operations console. The cookie holds a random token; only its
-- SHA-256 is stored. Sessions end after 30 minutes idle or 8 hours, whichever comes first.
CREATE TABLE admin.staff_sessions (
    token_hash      TEXT PRIMARY KEY,
    staff_id        UUID NOT NULL REFERENCES admin.staff(id),
    csrf_token      TEXT NOT NULL,
    ip              INET,
    user_agent      TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_seen_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at      TIMESTAMPTZ NOT NULL,
    revoked_at      TIMESTAMPTZ
);
CREATE INDEX ON admin.staff_sessions (staff_id);


CREATE TABLE admin.audit_log (
    id              BIGSERIAL,
    occurred_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    actor_type      TEXT NOT NULL CHECK (actor_type IN ('staff', 'system', 'merchant_member')),
    actor_id        UUID,
    actor_role      TEXT,
    action          TEXT NOT NULL,              -- pii.unmask, refund.approve, rule.update, permission.denied ...
    target_type     TEXT,
    target_id       UUID,
    result          TEXT NOT NULL CHECK (result IN ('allowed', 'denied', 'pending', 'failed')),  -- failed: allowed, but the change couldn't be made
    device          TEXT,
    ip              INET,
    detail          JSONB,
    prev_hash       TEXT,                       -- hash chain: tampering with any row breaks every later hash
    row_hash        TEXT NOT NULL,
    PRIMARY KEY (id, occurred_at)
) PARTITION BY RANGE (occurred_at);
CREATE TABLE admin.audit_log_2026_11 PARTITION OF admin.audit_log FOR VALUES FROM ('2026-11-01') TO ('2026-12-01');
CREATE TABLE admin.audit_log_2026_12 PARTITION OF admin.audit_log FOR VALUES FROM ('2026-12-01') TO ('2027-01-01');
CREATE TABLE admin.audit_log_default PARTITION OF admin.audit_log DEFAULT;
CREATE TRIGGER audit_append_only BEFORE UPDATE OR DELETE ON admin.audit_log
    FOR EACH ROW EXECUTE FUNCTION ledger.forbid_mutation();

-- ---------------------------------------------------------------------------
-- PLATFORM: idempotency, transactional outbox
-- ---------------------------------------------------------------------------
CREATE TABLE platform.idempotency_keys (
    key             TEXT NOT NULL,
    principal       TEXT NOT NULL,              -- user:<id> or apikey:<id>
    request_hash    TEXT NOT NULL,              -- same key with a different body is rejected (409)
    response_status SMALLINT,
    response_body   JSONB,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (principal, key)
);

-- Written in the same transaction as the state change; a relay publishes rows to Kafka and marks them sent.
CREATE TABLE platform.outbox (
    id              BIGSERIAL PRIMARY KEY,
    topic           TEXT NOT NULL,              -- payment.succeeded, order.placed, case.opened ...
    aggregate_id    UUID NOT NULL,
    payload         JSONB NOT NULL,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    published_at    TIMESTAMPTZ
);
CREATE INDEX ON platform.outbox (id) WHERE published_at IS NULL;

-- ---------------------------------------------------------------------------
-- NOTIFY: what users are told about, and where to push it
-- ---------------------------------------------------------------------------
-- One row per notification shown in the app. Built from outbox events; the unique key makes a redelivered
-- event (the relay is at-least-once) a no-op.
CREATE TABLE notify.notifications (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id         UUID NOT NULL REFERENCES identity.users(id),
    kind            TEXT NOT NULL,              -- money_received, payment_succeeded, payment_failed, topup_succeeded, security ...
    title           TEXT NOT NULL,              -- already in the user's language
    body            TEXT NOT NULL,
    data            JSONB NOT NULL DEFAULT '{}', -- e.g. {"intent_id": ...} so the app can open the right screen
    source_event    BIGINT NOT NULL,            -- platform.outbox.id
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    read_at         TIMESTAMPTZ,
    pushed_at       TIMESTAMPTZ,
    UNIQUE (user_id, source_event, kind)
);
CREATE INDEX ON notify.notifications (user_id, created_at DESC, id DESC);
CREATE INDEX ON notify.notifications (user_id) WHERE read_at IS NULL;

-- Firebase Cloud Messaging registration token for a signed-in device (Android, and iOS through FCM).
CREATE TABLE notify.push_tokens (
    device_id       UUID PRIMARY KEY REFERENCES identity.devices(id),
    user_id         UUID NOT NULL REFERENCES identity.users(id),
    token           TEXT NOT NULL UNIQUE,
    platform        TEXT NOT NULL CHECK (platform IN ('android', 'ios')),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX ON notify.push_tokens (user_id);

-- ---------------------------------------------------------------------------
-- ADMIN reference data: the roles and the permission matrix from the design (Roles and audit log).
-- full = act alone, approve = needs a second person, view = read only (masked).
-- ---------------------------------------------------------------------------
INSERT INTO admin.roles (id, name, description) VALUES
    ('super_admin', 'Super admin', 'Everything, but money and access changes still need a second person'),
    ('finance_officer', 'Finance officer', 'Refunds, payouts, reconciliation, commission'),
    ('risk_analyst', 'Risk analyst', 'Fraud cases, freezes, personal data when a case needs it'),
    ('support_agent', 'Support agent', 'Customer help, small refunds'),
    ('merchant_ops', 'Merchant ops', 'Merchant applications and onboarding'),
    ('content_editor', 'Content editor', 'Campaigns and banners');

INSERT INTO admin.role_permissions (role_id, permission, grant_level) VALUES
    ('super_admin', 'transactions.view', 'full'), ('finance_officer', 'transactions.view', 'full'),
    ('risk_analyst', 'transactions.view', 'full'), ('support_agent', 'transactions.view', 'view'),
    ('merchant_ops', 'transactions.view', 'view'),
    ('super_admin', 'pii.view', 'view'), ('risk_analyst', 'pii.view', 'view'), ('support_agent', 'pii.view', 'view'),
    ('super_admin', 'refunds.small', 'full'), ('finance_officer', 'refunds.small', 'full'), ('support_agent', 'refunds.small', 'full'),
    ('super_admin', 'refunds.large', 'approve'), ('finance_officer', 'refunds.large', 'approve'),
    ('super_admin', 'accounts.freeze', 'approve'), ('risk_analyst', 'accounts.freeze', 'approve'),
    ('super_admin', 'recon.resolve', 'full'), ('finance_officer', 'recon.resolve', 'full'),
    ('super_admin', 'commission.change', 'approve'), ('finance_officer', 'commission.change', 'approve'),
    ('super_admin', 'merchants.approve', 'full'), ('merchant_ops', 'merchants.approve', 'full'),
    ('risk_analyst', 'merchants.approve', 'view'),
    ('super_admin', 'campaigns.publish', 'full'), ('content_editor', 'campaigns.publish', 'approve'),
    ('super_admin', 'reports.export', 'full'), ('finance_officer', 'reports.export', 'full'),
    ('risk_analyst', 'reports.export', 'full'), ('merchant_ops', 'reports.export', 'view'),
    ('super_admin', 'staff.manage', 'approve'),
    ('super_admin', 'settings.change', 'approve'),
    -- Not in the design's matrix; added with the payout and audit screens.
    ('super_admin', 'payouts.release', 'approve'), ('finance_officer', 'payouts.release', 'approve'),
    ('risk_analyst', 'payouts.release', 'view'), ('merchant_ops', 'payouts.release', 'view'),
    ('super_admin', 'audit.view', 'full'), ('finance_officer', 'audit.view', 'full'), ('risk_analyst', 'audit.view', 'full'),
    -- Risk cases: working a case and declining a held payment (no money moves) vs. releasing one (money moves).
    ('super_admin', 'risk.cases', 'full'), ('risk_analyst', 'risk.cases', 'full'),
    ('finance_officer', 'risk.cases', 'view'), ('support_agent', 'risk.cases', 'view'),
    ('super_admin', 'payments.release', 'approve'), ('risk_analyst', 'payments.release', 'approve'),
    ('finance_officer', 'payments.release', 'approve'),
    -- Orders accepted but never handed over: refunding the customer or paying the shop moves money, so a
    -- second person approves either.
    ('super_admin', 'orders.settle', 'approve'), ('finance_officer', 'orders.settle', 'approve'),
    ('support_agent', 'orders.settle', 'approve'), ('risk_analyst', 'orders.settle', 'view'),
    ('merchant_ops', 'orders.settle', 'view');

